using System;using System.Linq;using System.Collections.Generic;using System.IO;using System.Text;using System.Runtime.Serialization.Json;using System.IO.Compression;using GlassBoard;
public static class ExperienceTests {
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static byte[] Json<T>(T value){using(var stream=new MemoryStream()){new DataContractJsonSerializer(typeof(T)).WriteObject(stream,value);return stream.ToArray();}}
 static T Read<T>(string path){using(var stream=File.OpenRead(path))return (T)new DataContractJsonSerializer(typeof(T)).ReadObject(stream);}
 static void Archive(string path,Dictionary<string,byte[]> data){using(var file=File.Create(path))using(var zip=new ZipArchive(file,ZipArchiveMode.Create))foreach(var item in data){using(var stream=zip.CreateEntry(item.Key).Open())stream.Write(item.Value,0,item.Value.Length);}}
 static void Reject(Action action,string label){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,label);}
 public static int Main(){
  var p=new Preferences();var h=new BoardEditHistory();var before=BoardEditState.Capture(p);p.Apps.Add(new Entry{Path="a.exe",Name="A",Group="游戏",ExtraGroups=new List<string>{"办公"}});Check(h.Remember(before,p,"添加"),"record add");p.Widgets.City="保留城市";Check(h.Undo(p)=="添加"&&p.Apps.Count==0&&p.Widgets.City=="保留城市","undo changes board only");Check(h.Redo(p)=="添加"&&p.Apps.Count==1&&FeatureRules.InGroup(p.Apps[0],"办公"),"redo restores shared memberships");before=BoardEditState.Capture(p);FeatureRules.Transfer(p,new[]{"a.exe"},"游戏","学习阅读");h.Remember(before,p,"移动");before=BoardEditState.Capture(p);EntryRules.Remove(p,new[]{"a.exe"},"学习阅读");h.Remember(before,p,"移除");Check(h.Undo(p)=="移除"&&FeatureRules.InGroup(p.Apps[0],"学习阅读"),"undo scoped removal");Check(h.Undo(p)=="移动"&&FeatureRules.InGroup(p.Apps[0],"游戏"),"undo move");before=BoardEditState.Capture(p);Check(!h.Remember(before,p,"无变化")&&h.CanRedo,"no-op retains redo");p.Apps[0].Name="新名字";h.Remember(before,p,"改名");Check(!h.CanRedo,"new operation invalidates redo");h.Clear();for(int i=0;i<45;i++){before=BoardEditState.Capture(p);p.Apps[0].Name="N"+i;h.Remember(before,p,"修改");}int count=0;while(h.CanUndo){h.Undo(p);count++;}Check(count==40,"history bounded to forty");
  var cache=new TrackArtworkCache<string>(2);DateTime now=DateTime.UtcNow;cache.Put("player|A","A art",now);Check(cache.Get("player|B",now)==null,"no cross-track artwork");cache.Put("player|B","B art",now.AddSeconds(1));cache.Put("player|C","C art",now.AddSeconds(2));Check(cache.Get("player|A",now.AddSeconds(3))==null&&cache.Get("player|C",now.AddSeconds(3))=="C art","artwork bounded eviction");Check(cache.Get("player|C",now.AddMinutes(16))==null,"artwork expires");
  var previous=new MediaSnapshot{Available=true,Source="cloudmusic.exe",Key="trackA",Title="歌曲 A",Artist="歌手",Cover="encoded",MetadataStatus="OK"};var current=new MediaSnapshot{Available=true,Source="cloudmusic.exe",Key="empty",Title="",MetadataStatus="failed",Playing=true};var recovered=MusicMetadataRecovery.Recover(previous,current);Check(recovered.Title==previous.Title&&recovered.Key==previous.Key&&recovered.Playing&&current.Key=="empty","temporary metadata failure preserves same-player identity without mutating input");current.Source="other.exe";Check(MusicMetadataRecovery.Recover(previous,current).Key=="empty","different player must not reuse metadata");
  string root=Path.Combine(Path.GetTempPath(),"glassboard-experience-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
   string source=Path.Combine(root,"source"),dest=Path.Combine(root,"dest");Directory.CreateDirectory(source);Directory.CreateDirectory(dest);Directory.CreateDirectory(Path.Combine(source,"schemes"));Directory.CreateDirectory(Path.Combine(source,"icons"));byte[] icon=Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jP1kAAAAASUVORK5CYII=");string iconPath=Path.Combine(source,"icons","custom.png");File.WriteAllBytes(iconPath,icon);p=new Preferences();p.Apps.Add(new Entry{Name="中文软件",Path="a.exe",Group="游戏",ExtraGroups=new List<string>{"办公"},IconPath=iconPath});p.BoardIconSize=30;p.Widgets.City="杭州";File.WriteAllBytes(Path.Combine(source,"layout.json"),Json(p));var notes=new NoteBook();notes.Normalize();notes.Selected.Title="备忘录";notes.Selected.Body="完整恢复中文内容";NoteFiles.Write(Path.Combine(source,"notes.json"),notes);var scheme=FeatureRules.Capture(p,"测试方案");File.WriteAllBytes(Path.Combine(source,"schemes","saved.json"),Json(scheme));string backup=Path.Combine(root,"full.gbbackup");BackupFiles.Create(source,backup);var data=BackupFiles.Read(backup);Check(data.ContainsKey("layout.json")&&data.ContainsKey("notes.json")&&data.Keys.Any(k=>k.StartsWith("icons/")),"backup includes settings notes schemes and custom icons");Directory.CreateDirectory(Path.Combine(dest,"schemes"));File.WriteAllBytes(Path.Combine(dest,"schemes","obsolete.json"),Json(scheme));BackupFiles.Restore(backup,dest);var restored=Read<Preferences>(Path.Combine(dest,"layout.json"));restored.Normalize();Check(restored.BoardIconSize==30&&restored.Widgets.City=="杭州"&&FeatureRules.InGroup(restored.Apps[0],"办公"),"complete settings roundtrip");Check(Read<NoteBook>(Path.Combine(dest,"notes.json")).Items[0].Body=="完整恢复中文内容","note text roundtrip");Check(File.Exists(restored.Apps[0].IconPath)&&File.ReadAllBytes(restored.Apps[0].IconPath).SequenceEqual(icon)&&restored.Apps[0].IconPath.StartsWith(dest),"portable custom icon rebased unchanged");Check(Read<AppearanceScheme>(Path.Combine(dest,"schemes","saved.json")).Apps[0].IconPath.StartsWith(dest),"scheme icon rebased");Check(!File.Exists(Path.Combine(dest,"schemes","obsolete.json")),"scheme set restored");
   byte[] original=File.ReadAllBytes(Path.Combine(dest,"layout.json"));string bad=Path.Combine(root,"bad.gbbackup");var invalid=new Dictionary<string,byte[]>(data);invalid["../escape.json"]=Encoding.UTF8.GetBytes("{}");Archive(bad,invalid);Reject(()=>BackupFiles.Restore(bad,dest),"reject archive traversal");Check(File.ReadAllBytes(Path.Combine(dest,"layout.json")).SequenceEqual(original),"invalid archive leaves existing settings unchanged");invalid=new Dictionary<string,byte[]>(data);invalid["layout.json"]=Encoding.UTF8.GetBytes("broken JSON");Archive(bad,invalid);Reject(()=>BackupFiles.Restore(bad,dest),"reject malformed settings");Check(File.ReadAllBytes(Path.Combine(dest,"layout.json")).SequenceEqual(original),"malformed JSON leaves settings unchanged");
   string failure=Path.Combine(root,"failure");Directory.CreateDirectory(failure);Directory.CreateDirectory(Path.Combine(failure,"notes.json"));File.WriteAllBytes(Path.Combine(failure,"layout.json"),Json(new Preferences{BoardIconSize=76}));byte[] old=File.ReadAllBytes(Path.Combine(failure,"layout.json"));Reject(()=>BackupFiles.Restore(backup,failure),"forced multi-file write failure");Check(File.ReadAllBytes(Path.Combine(failure,"layout.json")).SequenceEqual(old),"blocked destination leaves settings unchanged");Directory.Delete(Path.Combine(failure,"notes.json"));Reject(()=>BackupFiles.Restore(backup,failure,name=>{if(name=="layout.json")throw new IOException("forced after first commit");}),"forced failure after first commit");Check(File.ReadAllBytes(Path.Combine(failure,"layout.json")).SequenceEqual(old),"restore rolls back files committed before failure");Check(!Directory.GetDirectories(failure,".restore-*").Any(),"successful rollback cleans staging folder");
  }finally{Directory.Delete(root,true);}
  Console.WriteLine("PASS: forty-step undo/redo, board-only snapshots, shared groups, artwork identity/expiry, metadata isolation, complete backup/portable icons/notes, invalid archive rejection and multi-file restore rollback.");return 0;
 }
}
